const inputData = $input.first()?.json ?? {};
const { date, time, guests = 2, location = 'Center' } = inputData;
if (!date || !time) { throw new Error('Missing required parameters: date or time'); }
return { date, time, guests: parseInt(guests, 10), location, searchTimestamp: new Date().toISOString() };

const dbResults = $input.first()?.json ?? {};
const previousData = $input.all()[0]?.json ?? {};
const results = Array.isArray(dbResults) ? dbResults : [dbResults];
const formattedResults = results.map(item => ({ id: item.id, name: item.name, area: item.area, capacity: item.capacity, rating: parseFloat(item.rating), time_slot: item.time_slot, features: typeof item.features === 'string' ? JSON.parse(item.features) : item.features })).slice(0, 3);
return { status: 'success', search_params: { date: previousData.date, time: previousData.time, guests: previousData.guests, location: previousData.location }, results_count: formattedResults.length, results: formattedResults, timestamp: new Date().toISOString() };

const error = $input.first()?.json?.error ?? new Error('Database error');
const previousData = $input.all()[0]?.json ?? {};
return { status: 'error', error_type: 'database_error', message: error.message || 'Worker execution failed', context: { date: previousData.date, time: previousData.time, location: previousData.location }, timestamp: new Date().toISOString() };
